import fs from 'node:fs';import{pathToFileURL}from'node:url';
const base=new URL('.',pathToFileURL(process.argv[2]));const{McpHost}=await import(new URL('host.js',base));const{DeterministicLiveSimulator,LiveMutationNotDispatchedError}=await import(new URL('live.js',base));
function clean(v){v=structuredClone(v);function walk(x){if(!x||typeof x!=='object')return;for(const[k,w]of Object.entries(x)){if(typeof w==='string'&&w.startsWith('transport_'))x[k]='$transaction';else if(k==='expiresAt')x[k]='$time';else walk(w);}}if(v?.result?.content?.[0]?.text)try{v.result.content[0].text=JSON.parse(v.result.content[0].text);}catch{}walk(v);return v;}
const fieldNames=['position','loopEnabled','loopStart','loopLength','metronome','punchIn','punchOut'];
const rows=[];for(const tool of ['liveTransportPreviewAsync','liveTransportApplyAsync']){const valid=tool.includes('Preview')?{position:4}:{transactionId:'missing',confirmation:'apply',idempotencyKey:'apply-key'};const cases=[null,[],{},0,false,'x',valid,{...valid,extra:true}];for(const key of (tool.includes('Preview')?fieldNames:Object.keys(valid))){const omitted={...valid};delete omitted[key];cases.push(omitted);for(const value of [null,[],{},false,true,-1,0,0.25,4,1e308,'','x','a'.repeat(257)])cases.push({...valid,[key]:value});}for(const args of cases){const host=new McpHost(new DeterministicLiveSimulator());let result;try{result=clean(await host[tool](1,args));}catch(e){result={error:e.message};}rows.push({tool,args,result});}}
const fields=[];for(const field of fieldNames)for(const value of [false,true,0,4,0.25])for(const observed of [null,false,true,0,4,3.74,4.26,4.260001,3.739999,6.5,6.50001,4.00000001,0.25])for(const playing of [false,true]){const transport={playing,position:observed,loop:{enabled:observed,start:observed,length:observed},metronome:observed,punchIn:observed,punchOut:observed};fields.push({field,value,transport,result:McpHost.transportFieldIs(transport,field,value)});}
const workflows=[];const proposals=[{position:4},{loopEnabled:true,loopStart:2,loopLength:8},{metronome:true,punchIn:true,punchOut:true},{position:4,loopEnabled:true,loopStart:2,loopLength:8,metronome:true,punchIn:true,punchOut:true}];
for(const proposed of proposals)for(const scenario of ['normal','expire','epoch','identity-edit','revision-edit','missing-identity','apply-before','apply-after','apply-refusal','apply-no-effect','apply-read','apply-current-read','apply-preabort','undo-before','undo-after','undo-refusal','undo-no-effect','undo-read','undo-current-read','undo-other-identity','undo-other-fields','undo-playing','undo-position-edit','undo-recording','undo-epoch']){
const sim=new DeterministicLiveSimulator(),calls=[],cache=new Map();let fault='',fired=false,afterInvoke=false;if(scenario==='missing-identity')delete sim.state.set.objectIdentity;
function context(c){return c?{deadline:c.deadlineMs!==undefined,...(c.idempotencyKey?{idempotencyKey:c.idempotencyKey}:{}),...(c.transactionId?{transactionId:c.transactionId}:{})}:null;}
function readFault(){if(!fired&&((fault.endsWith('-read')&&afterInvoke)||fault==='apply-current-read'||fault==='undo-current-read')){fired=true;throw Error('injected authoritative read failure');}}
function invoke(i,c){calls.push(clean({method:'invoke',invocation:i,context:context(c)}));const key=JSON.stringify([c?.transactionId,c?.idempotencyKey,i]);if(cache.has(key))return cache.get(key);if(!fired&&['before','refusal'].some(s=>fault.endsWith(s))){fired=true;throw fault.endsWith('refusal')?new LiveMutationNotDispatchedError('mutation was not dispatched: ownership changed'):Error('injected operation failure');}const noEffect=!fired&&fault.endsWith('no-effect');const result=noEffect?{ok:true}:sim.invoke(i);if(noEffect)fired=true;else cache.set(key,result);afterInvoke=true;if(!fired&&fault.endsWith('after')){fired=true;throw Error('injected operation failure');}return result;}
const adapter={status:()=>sim.status(),snapshot:()=>sim.snapshot(),get:r=>sim.get(r),invoke:i=>invoke(i),subscribe:l=>sim.subscribe(l),reconnect:()=>sim.reconnect(),snapshotAsync:async(c,r)=>{calls.push(clean({method:'snapshot',request:r??null,context:context(c)}));readFault();return sim.snapshotAsync(c,r)},discoverAsync:async(r,c)=>{calls.push(clean({method:'discover',request:r,context:context(c)}));readFault();return sim.discoverAsync(r,c)},getAsync:async(r,c)=>{calls.push(clean({method:'get',reference:r,context:context(c)}));readFault();return sim.get(r)},invokeAsync:async(i,c)=>invoke(i,c),refreshStatusAsync:async(c)=>{calls.push(clean({method:'status',context:context(c)}));return sim.status()}};
const host=new McpHost(adapter),results=[],states=[];const preview=await host.liveTransportPreviewAsync(1,proposed);results.push(clean(preview));const body=JSON.parse(preview.result.content[0].text);const txid=body.transactionId;
if(txid){const record=host.transportTransactions.get(txid);async function perform(action,key){const args={transactionId:txid,confirmation:action,idempotencyKey:key};const controller=new AbortController();if(scenario==='apply-preabort')controller.abort();results.push(clean(action==='apply'?await host.liveTransportApplyAsync(results.length+1,args,controller.signal):await host.liveUndoAsync(results.length+1,args)));states.push(clean(record));}
if(scenario==='expire')record.expiresAt=0;if(scenario==='epoch')sim.reconnect();if(scenario==='identity-edit')sim.state.set.objectIdentity='other';if(scenario==='revision-edit')sim.state.playback.revision='manual';if(scenario.startsWith('apply-'))fault=scenario;
for(const key of ['apply-key','other-key','apply-key'])await perform('apply',key);fault='';fired=false;afterInvoke=false;
if(scenario==='undo-other-identity')sim.state.set.objectIdentity='other';if(scenario==='undo-other-fields'){sim.state.playback.transport.loop.length=12;sim.state.playback.transport.metronome=false;}if(scenario==='undo-playing')sim.state.playback.transport.playing=true;if(scenario==='undo-position-edit')sim.state.playback.transport.position=8;if(scenario==='undo-recording'){sim.state.playback.transport.sessionRecord=true;sim.state.playback.revision='manual';}if(scenario==='undo-epoch')sim.reconnect();if(scenario.startsWith('undo-')&&!['undo-other-identity','undo-other-fields','undo-playing','undo-position-edit','undo-recording','undo-epoch'].includes(scenario))fault=scenario;
for(const key of ['undo-key','other-undo-key','undo-key'])await perform('undo',key);fault='';fired=false;afterInvoke=false;await perform('undo','new-undo-key');}
workflows.push({proposed,scenario,results,states,calls,state:sim.state});}
fs.writeFileSync(new URL('host-transport-oracle.json',import.meta.url),JSON.stringify({rows,fields,workflows}));console.log({rows:rows.length,fields:fields.length,workflows:workflows.length});
